baseline = {2: [1000, 1002, 999], 5: [2000, 2001, 2000]}
activity = {2: [1000, 1400, 1001], 5: [2000, 2001, 2000]}

def span(values):
    return max(values) - min(values)

candidates = [slot for slot in baseline
              if span(activity[slot]) > span(baseline[slot]) + 64]
assert candidates == [2]
# Explicit acceptance follows review; a candidate is not a physical name.
accepted = {2: 'DEMO KNOB'}

# Invented, aligned copies of one button's two presses.
track = [0, 1, 1, 0, 0, 1, 0]
aliases = {4 + 5 * column: track[:] for column in range(8)}
assert all(values == track for values in aliases.values())

def press_count(values):
    return sum(bool(right and not left)
               for left, right in zip(values, values[1:]))

assert sum(press_count(v) for v in aliases.values()) == 16
assert press_count(aliases[4]) == 2
print('candidate slots:', candidates)
print('accepted:', accepted)
print('DEL press events:', press_count(aliases[4]))

